H.background();
const w = H.W, h = H.H;
const g = 9.8;
const L = Math.max(0.1, P.L);
const theta0deg = P.theta0;
const theta0 = theta0deg * Math.PI / 180;
const omega = Math.sqrt(g / L);
const T = 2 * Math.PI / omega;
const theta = theta0 * Math.cos(omega * t);
// pivot near top-center; pendulum length in px scales with L but stays on-screen
const px = w * 0.5, py = h * 0.18;
const Lpx = Math.min(h * 0.6, 70 * L + 60);
const bx = px + Lpx * Math.sin(theta);
const by = py + Lpx * Math.cos(theta);
// ceiling
H.line(px - 80, py, px + 80, py, { color: H.colors.axis, width: 3 });
// reference vertical (equilibrium)
H.line(px, py, px, py + Lpx + 20, { color: H.colors.grid, width: 1, dash: [5, 5] });
// arc showing swing amplitude
const arc = [];
for (let i = 0; i <= 40; i++) {
  const a = -theta0 + (2 * theta0) * i / 40;
  arc.push([px + (Lpx + 18) * Math.sin(a), py + (Lpx + 18) * Math.cos(a)]);
}
H.path(arc, { color: H.colors.grid, width: 1.5, dash: [4, 4] });
// the rod and bob
H.line(px, py, bx, by, { color: H.colors.violet, width: 2.5 });
H.circle(px, py, 4, { fill: H.colors.axis });
H.circle(bx, by, 16, { fill: H.colors.accent, stroke: H.colors.bg, width: 2 });
// angle label
H.text("theta", px + 10, py + 40, { color: H.colors.sub, size: 13 });
// gravity restoring component arrow (tangential): magnitude ~ -g sin(theta)
const tangent = -g * Math.sin(theta);
const tx = Math.cos(theta), ty = -Math.sin(theta); // tangent direction in screen coords
H.arrow(bx, by, bx + tangent * tx * 6, by + tangent * ty * 6, { color: H.colors.warn, width: 2.5, head: 10 });
H.text("Simple pendulum:  T = 2·pi·sqrt(L/g)", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("L = " + L.toFixed(2) + " m   theta0 = " + theta0deg.toFixed(0) + " deg   T = " + T.toFixed(2) + " s   theta = " + (theta * 180 / Math.PI).toFixed(1) + " deg", 24, 52, { color: H.colors.sub, size: 13 });
